sys_ui_policy.script_false:
function onCondition() {
	var fields = ['solicitante', 'data_e_hora_da_solicitacao', 'numero', 'tipo', 'prioridade', 'descricao', 'descricao_resumida'];

	//Loop atraves de cada campo na lista
	for (var i = 0; i < fields.length; i++) {
		//Torna o campo solemte leitura
		g_form.setReadOnly(fields[i], false);
	}
}

sys_ui_policy.script_true:
function onCondition() {
	var fields = ['solicitante', 'data_e_hora_da_solicitacao', 'numero', 'tipo', 'prioridade', 'descricao', 'descricao_resumida'];

	//Loop atraves de cada campo na lista
	for (var i = 0; i < fields.length; i++) {
		//Torna o campo solemte leitura
		g_form.setReadOnly(fields[i], true);
	}
}
